script='''
const data=JSON.parse(document.getElementById('researchData').textContent);
const names=JSON.parse(document.getElementById('methodNames').textContent);
const $=id=>document.getElementById(id);
const item=$('item'),variant=$('variant'),methodA=$('methodA'),methodB=$('methodB'),bg=$('background');
const key=(id,v,m)=>`${id}/${v}/${m}`;
const masks=new Map(data.masks.map(x=>[key(x.id,x.variant,x.method),x.ink]));
for(const id of Object.keys(data.sources))item.add(new Option(id,id));
function refreshVariants(){const old=variant.value;variant.innerHTML='';for(const v of [...new Set(data.masks.filter(x=>x.id===item.value&&!x.method.startsWith('sweep')).map(x=>x.variant))])variant.add(new Option(v,v));variant.value=[...variant.options].some(o=>o.value===old)?old:'original';refreshMethods()}
function refreshMethods(){const list=[...new Set(data.masks.filter(x=>x.id===item.value&&x.variant===variant.value&&!x.method.startsWith('sweep')).map(x=>x.method))];for(const [sel,def] of [[methodA,'stencil_auto'],[methodB,'edges_clean']]){const prev=sel.value;sel.innerHTML='';for(const m of list)sel.add(new Option(names[m]||m,m));sel.value=list.includes(prev)?prev:list.includes(def)?def:list[0]}render()}
function pixels(canvas,source,isMask){canvas.width=16;canvas.height=16;const ctx=canvas.getContext('2d');const img=ctx.createImageData(16,16);for(let p=0;p<256;p++){const x=p%16,y=Math.floor(p/16);const light=bg.value==='light';let c=light?[244,246,248]:bg.value==='dark'?[20,23,29]:((Math.floor(x/2)+Math.floor(y/2))%2?[39,43,51]:[30,33,39]);if(isMask){if(source[p]==='1')c=light?[28,32,38]:[240,246,240]}else if(source[p*4+3]>=128)c=source.slice(p*4,p*4+3);img.data.set([...c,255],p*4)}ctx.putImageData(img,0,0)}
function sample(parent,title,source,isMask){const card=document.createElement('div');card.className='sample';const h=document.createElement('h3');h.textContent=title;card.append(h);const zoom=document.createElement('canvas');zoom.className='zoom';pixels(zoom,source,isMask);card.append(zoom);const native=document.createElement('div');native.className='native';const small=document.createElement('canvas');small.style.width='16px';small.style.height='16px';pixels(small,source,isMask);native.append(small,document.createTextNode('Native 16 × 16'));card.append(native);parent.append(card)}
function render(){const parent=$('samples');parent.innerHTML='';sample(parent,'Original colored source',data.sources[item.value],false);const a=masks.get(key(item.value,variant.value,methodA.value)),b=masks.get(key(item.value,variant.value,methodB.value));sample(parent,names[methodA.value]||methodA.value,a,true);sample(parent,names[methodB.value]||methodB.value,b,true);const ink=s=>[...s].filter(v=>v==='1').length;const differences=[...a].filter((v,i)=>v!==b[i]).length;$('sampleStats').textContent=`Candidate A: ${ink(a)} ink pixels · B: ${ink(b)} ink pixels · ${differences} pixels differ. The source panel always shows the original artwork; input preparation applies to the two candidates.`;renderSweep()}
function renderSweep(){const p=$('sweepSamples');p.innerHTML='';const t=$('sweep').value;$('sweepValue').textContent=t;for(const style of ['solid','stencil'])sample(p,`${style==='solid'?'Solid threshold':'Stencil Cuts'} ${t}`,masks.get(key('breastplate-1-1','original',`sweep_${style}_${t}`)),true)}
item.addEventListener('change',refreshVariants);variant.addEventListener('change',refreshMethods);methodA.addEventListener('change',render);methodB.addEventListener('change',render);bg.addEventListener('change',render);$('sweep').addEventListener('input',renderSweep);refreshVariants();
'''
doc=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bitify — one-color inventory icon research</title><style>{style}</style><main>{body}</main><script type="application/json" id="researchData">{json.dumps(data,separators=(",",":"))}</script><script type="application/json" id="methodNames">{json.dumps(names)}</script><script>{script}</script></html>'
(ROOT/'report.html').write_text(doc,encoding='utf-8')
assert not any(key in doc for key in replacements if key.endswith('_IMG') or key.endswith('_TABLE'))
print(f'Wrote self-contained report.html ({len(doc):,} characters).')
